mapper.select:
SELECT MONTH(t.completion_time) AS monthNo, COUNT(*) AS purchaseCount, SUM(t.control_amount) AS budgetAmount, SUM(t.award_amount) AS awardAmount FROM ( SELECT l.control_amount, bi.tax_price AS award_amount, br.notifi_time AS completion_time FROM tb_purchase_ledger l INNER JOIN tb_bidding_result br ON br.id = ( SELECT br2.id FROM tb_bidding_result br2 WHERE br2.notice_id = l.notice_id AND br2.bid_result = 1 AND br2.del_flag = 0 ORDER BY br2.update_time DESC LIMIT 1 ) INNER JOIN tb_bidding_info bi ON bi.id = br.bidding_info_id WHERE l.grain = 'TASK' AND l.status = 'completed' AND br.notifi_time IS NOT NULL
AND ( l.org_id = #{orgId} OR l.org_id IN ( SELECT t.thrid_dept_id FROM sys_dept t WHERE FIND_IN_SET( (SELECT dept_id FROM sys_dept WHERE thrid_dept_id = #{orgId}), t.ancestors) ) )
AND YEAR(br.notifi_time) = #{year}
) t GROUP BY MONTH(t.completion_time)
